def collapse_ints(nums: list[int]) -> str:
    """See SPEC.md."""
    uniq = sorted(set(nums))
    parts: list[str] = []
    i = 0
    n = len(uniq)
    while i < n:
        j = i
        while j + 1 < n and uniq[j + 1] == uniq[j] + 1:
            j += 1
        if j - i + 1 >= 4:
            a, b = uniq[i], uniq[j]
            parts.append(f"({a})-{b}" if a < 0 else f"{a}-{b}")
        else:
            parts.extend(str(x) for x in uniq[i:j + 1])
        i = j + 1
    return ",".join(parts)

